mapper.insert:
INSERT INTO crowd_count (
    id, area_id, count, count_time, panoramic_image, density
) VALUES (
    #{id}, #{areaId}, #{count}, #{countTime}, #{panoramicImage}, #{density}
)

mapper.select:
SELECT * FROM crowd_count 
WHERE area_id = #{areaId} 
AND count_time BETWEEN #{startTime} AND #{endTime}
ORDER BY count_time DESC

SELECT AVG(count) FROM crowd_count 
WHERE area_id = #{areaId} 
AND count_time BETWEEN #{startTime} AND #{endTime}

SELECT MAX(count) FROM crowd_count 
WHERE area_id = #{areaId} 
AND count_time BETWEEN #{startTime} AND #{endTime}

SELECT * FROM crowd_count 
WHERE area_id = #{areaId} 
AND count > #{threshold}
AND count_time BETWEEN #{startTime} AND #{endTime}
ORDER BY count DESC

SELECT density FROM crowd_count 
WHERE area_id = #{areaId} 
AND count_time = #{time}

SELECT * FROM crowd_count 
WHERE area_id = #{areaId} 
AND count_time BETWEEN #{startTime} AND #{endTime}
ORDER BY count_time ASC
